/* Focused reading controls and provider-reported account information. */
let readerTrail=[],readerRequest=0,usageSnapshot=null,usagePending=false;
function citationLink(c){const label=esc((c.ref?'[资料'+c.ref+'] ':'')+c.title+' · '+c.type);if(c.id&&c.kind==='article')return `<button class="citation-link" data-open="${esc(c.id)}">${label}</button>`;if(c.id&&['document','minutes'].includes(c.kind))return `<button class="citation-link" data-document="${esc(c.id)}" data-kind="${esc(c.kind)}">${label}</button>`;return `<a href="${safeUrl(c.url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`}
function tokenNumber(n){return Number(n||0).toLocaleString('zh-CN')}
function balanceText(balance){if(!balance.balances?.length)return balance.status==='unconfigured'?'待配置':balance.status==='unsupported'?'不支持查询':'暂不可用';return balance.balances.map(b=>(b.currency==='CNY'?'¥':'$')+Number(b.total_balance).toFixed(2)).join(' / ')}
async function refreshUsage(force=false){if(usagePending)return;usagePending=true;try{const d=await api('/ai-usage'+(force?'?refresh=1':''));usageSnapshot=d;const card=$('#ai-usage');if(!card)return;const u=d.usage.today,b=d.balance;card.innerHTML=`<div class="usage-title"><strong>${esc(d.provider)}</strong><button class="btn text" data-work="usage-detail" aria-label="查看接口用量明细">明细 ↗</button></div><div class="usage-row"><span>账户余额${b.status==='error'&&b.balances?.length?' · 上次':''}</span><strong>${esc(balanceText(b))}</strong></div><div class="usage-row"><span>今日用量</span><strong>${tokenNumber(u.total_tokens)} <small>tokens</small></strong></div><small class="usage-caption">${u.calls>u.measured_calls?'部分调用未返回用量':b.status==='error'?'余额更新失败，可点明细重试':'仅统计主一内的接口调用'}</small>`}catch{const card=$('#ai-usage');if(card)card.innerHTML='<span class="muted">用量暂不可用</span><button class="btn text" data-work="usage-refresh">重试</button>'}finally{usagePending=false}}
function usageDetail(){const d=usageSnapshot;if(!d)return;const b=d.balance;showDialog('#organize-dialog',d.provider+' · 用量与余额',`<div class="balance-summary"><span>账户余额${b.status==='error'?'（上次记录）':''}</span><strong>${esc(balanceText(b))}</strong><p class="muted">${esc(b.message||'余额由服务商实时接口返回，每 5 分钟更新。')}${b.updated_at?' 上次成功：'+fmt(b.updated_at):''}</p></div><table class="usage-table"><thead><tr><th>范围</th><th>调用</th><th>输入 tokens</th><th>输出 tokens</th><th>总 tokens</th></tr></thead><tbody>${[['today','今日'],['month','本月'],['all','累计']].map(([k,label])=>{const u=d.usage[k];return `<tr><th>${label}</th><td>${u.calls}</td><td>${tokenNumber(u.prompt_tokens)}</td><td>${tokenNumber(u.completion_tokens)}</td><td>${tokenNumber(u.total_tokens)}</td></tr>`}).join('')}</tbody></table><p class="data-note">${esc(d.scope)}<br>记录起点：${fmt(d.started_at)}。累计 ${d.usage.all.measured_calls} 次调用返回了用量；未返回的调用不按零消耗计费。本页不估算费用。</p>`,`<button class="btn" data-work="usage-refresh">刷新余额</button>`)}
async function attentionAction(action,b){if(action==='reader-back'){const previous=readerTrail.at(-1);if(previous){await openArticle(previous.id,{back:true});readerTrail.pop();const back=$('[data-work="reader-back"]');if(!readerTrail.length)back?.remove();$('.reader-main').scrollTop=previous.main;$('.reader-aside').scrollTop=previous.aside}return true}
 if(action==='usage-detail'){usageDetail();return true}if(action==='usage-refresh'){await refreshUsage(true);usageDetail();return true}
 if(action==='delete-message'){if(await confirmAction('删除这条聊天记录？','仅移除此条记录，可在本议事的消息回收站恢复。后续对话及自动整理的记录将排除它。')){await api('/messages',{id:b.dataset.id,action:'trash'});if(state.view==='assistant')await renderAssistant();else b.closest('.chat-message')?.remove();toast('消息已移入回收站')}return true}
 if(action==='message-trash'){const rows=await api('/message-trash?scope='+encodeURIComponent(state.scope));showDialog('#organize-dialog','消息回收站',rows.length?rows.map(r=>`<div class="message-trash-row"><div><small>${r.role==='user'?'我的提问':'AI 答复'} · ${fmt(r.created)}</small><p>${esc(r.content.slice(0,200))}${r.content.length>200?'…':''}</p></div><button class="btn" data-work="restore-message" data-id="${esc(r.id)}">恢复</button></div>`).join(''):empty('本议事没有已删除的消息'));return true}
 if(action==='restore-message'){await api('/messages',{id:b.dataset.id,action:'restore'});await attentionAction('message-trash',b);await renderAssistant();return true}return false}
let clearingMark=false;
async function clearInlineMark(e){const target=e.target.closest?.('[data-mark-ids]');if(!target||clearingMark)return;if(e.type==='keydown'&&!['Enter',' '].includes(e.key))return;if(e.type==='click'&&!window.getSelection().isCollapsed)return;if(e.type==='keydown')e.preventDefault();const id=state.article?.id;if(!id)return;clearingMark=true;try{await api('/notes',{action:'clear-style',ids:target.dataset.markIds.split(',').filter(Boolean)});await refreshNotes(id);clearSelection();toast('此处标记已取消，文字批注已保留')}catch(err){toast(err.message)}finally{clearingMark=false}}
document.addEventListener('click',clearInlineMark);document.addEventListener('keydown',clearInlineMark);
setInterval(()=>{if(!document.hidden)refreshUsage().catch(()=>{})},60000);
